ChatMessageRead:
  description: Private read only. Legacy and user bodies keep their original representation; proven ordered assistant bodies are read through their bound parts cursor.
  oneOf:
    - $ref: '#/components/schemas/ChatMessage'
    - $ref: '#/components/schemas/OrderedAssistantMessageRead'
    - $ref: '#/components/schemas/CancelledAssistantMessageRead'
    - $ref: '#/components/schemas/RegeneratedAssistantMessageRead'
OrderedAssistantMessageRead:
  type: object
  required: [message_id, role, content, status, created_at, run_id, rendering]
  additionalProperties: false
  properties:
    selected_skill_source_refs:
      type: array
      maxItems: 16
      uniqueItems: true
      items: { type: string, pattern: '^skill:(?!skill:)[A-Za-z0-9][A-Za-z0-9._:-]{0,190}(?![\s\S])' }
    message_id: { type: string, minLength: 1 }
    role:
      type: string
      const: assistant
    content: { type: 'null', description: Body is not inlined; read the exact ordered Message parts. }
    rendering: { $ref: '#/components/schemas/OrderedMessageRendering' }
    terminal_status: { type: string, const: cancelled }
    regenerated_from_message_id: { type: string, minLength: 1, maxLength: 256 }
    status:
      type: string
      enum: [pending, streaming, completed, failed]
    created_at: { type: string, format: date-time }
    run_id: { type: string, minLength: 1 }
    failure:
      type: object
      required: [source, code, retryable]
      additionalProperties: false
      properties:
        source: { type: string, const: agent }
        code:
          type: string
          enum:
            - token_budget_exceeded
            - recursion_limit_exceeded
            - assembly_failed
            - enqueue_failed
            - dispatch_exhausted
            - contract_incompatible
            - internal_error
            - model_unavailable
            - dependency_unavailable
            - model_access_denied
            - model_settlement_pending
        retryable: { type: boolean }
      if:
        properties:
          retryable: { const: true }
      then:
        properties:
          code: { enum: [model_unavailable, dependency_unavailable] }
  allOf:
    - if:
        properties: { failure: {} }
        required: [failure]
      then:
        required: [run_id]
        properties:
          role: { const: assistant }
          status: { const: failed }
          run_id: { type: string, minLength: 1 }
    - if:
        required: [terminal_status]
      then:
        properties:
          status: { const: failed }
        not: { required: [failure] }
